82	function captureSource<Data, Edge, ID>(
83	  value: unknown,
84	): NormalizedWalkSource<Data, Edge, ID> {
85	  if (
86	    value === null ||
87	    (typeof value !== 'object' && typeof value !== 'function') ||
88	    Array.isArray(value)
89	  )
90	    throw new TypeError('Walking source must be an object or function');
91	  const hydration: unknown = Reflect.get(value, 'hydration');
92	  const roots: unknown = Reflect.get(value, 'roots');
93	  const outgoing: unknown = Reflect.get(value, 'outgoing');
94	  const resolveVertex: unknown = Reflect.get(value, 'resolveVertex');
95	  if (
96	    typeof roots !== 'function' ||
97	    typeof outgoing !== 'function' ||
98	    (hydration !== 'resolver' && hydration !== 'inlineOrCached') ||
99	    (hydration === 'resolver'
100	      ? typeof resolveVertex !== 'function'
101	      : resolveVertex !== undefined)
102	  ) {
103	    throw new TypeError(
104	      'Walking source requires roots/outgoing and explicit hydration with a resolver only in resolver mode',
105	    );
106	  }
107	  // Only invocation signatures cross this unknown-input boundary. Callers are
108	  // invoked by the sessions, which validate their returned protocols/results.
109	  return {
110	    hydration,
111	    receiver: value,
112	    roots,
113	    outgoing,
114	    resolveVertex,
115	  } as NormalizedWalkSource<Data, Edge, ID>;
116	}
