184	    snapshot['revisit'] === undefined
185	      ? previous?.revisit ?? 'once'
186	      : snapshot['revisit'];
187	  if (revisit !== 'once' && revisit !== 'simplePaths' && revisit !== 'walks') {
188	    throw new TypeError('Unknown walking revisit policy');
189	  }
190	  const limitsInput =
191	    snapshot[previous === undefined ? 'limits' : 'replaceLimits'];
192	  const limits = copyLimits(
193	    limitsInput === undefined ? previous?.limits ?? {} : limitsInput,
194	  );
195	  if (
196	    revisit !== 'once' &&
197	    limits.maxDepth === undefined &&
198	    limits.maxCandidateReadAttempts === undefined
199	  ) {
200	    throw new TypeError(
201	      'Route enumeration requires maxDepth or maxCandidateReadAttempts',
202	    );
203	  }
204	  const shouldFollowEdge =
205	    snapshot['shouldFollowEdge'] === undefined
206	      ? previous?.shouldFollowEdge
207	      : snapshot['shouldFollowEdge'] === null
208	      ? undefined
209	      : snapshot['shouldFollowEdge'];
210	  const shouldExpandVertex =
211	    snapshot['shouldExpandVertex'] === undefined
212	      ? previous?.shouldExpandVertex
213	      : snapshot['shouldExpandVertex'] === null
214	      ? undefined
215	      : snapshot['shouldExpandVertex'];
216	  if (
217	    (shouldFollowEdge !== undefined &&
218	      typeof shouldFollowEdge !== 'function') ||
219	    (shouldExpandVertex !== undefined &&
220	      typeof shouldExpandVertex !== 'function')
221	  ) {
222	    throw new TypeError('Walking predicates must be callbacks');
223	  }
224	  const visitorInput =
225	    snapshot['visitors'] === undefined
226	      ? {}
227	      : object(snapshot['visitors'], 'Walking visitors must be a phase map');
