230	    const entries = visitorInput[phase];
231	    return entries === undefined
232	      ? copyVisitorRecords(previous?.visitors[phase] ?? [])
233	      : normalizeVisitorDefinitions<WalkVisitor<Data, Edge, Phase, ID>>(
234	          entries as VisitorPhaseInput<WalkVisitor<Data, Edge, Phase, ID>>,
235	        );
236	  }
237	  const defaults = normalizeTraversalExecutionOptions(phases, {
238	    emitEvents: [GraphWalkPhase.VERTEX],
239	    visitorPhases: 'all',
240	  });
