242	    phases,
243	    Object.fromEntries(
244	      Object.entries(snapshot).filter(([key]) =>
245	        ['emitEvents', 'visitorPhases'].includes(key),
246	      ),
247	    ) as TraversalIterableConfigInput<GraphWalkPhase>,
248	    previous?.execution ?? defaults,
249	  );
250	  return {
251	    source,
252	    strategy,
253	    revisit,
254	    limits,
