1	import type { Outcome } from '@core/effects/types';
2	import type { VisitorRecord } from '@core/graph/types';
3	import { normalizeTraversalExecutionOptions } from '@core/normalizeTraversalExecutionOptions';
4	import type { TraversalStopReason } from '@core/TraversalRunner';
5	import { TraversalRunnerStatus as Status } from '@core/TraversalRunner';
6	import type { TraversalIterableConfigInput } from '@core/TraversalRunnerIterableConfig';
7	import type { GraphWalkEdge, GraphWalkEvent } from '../GraphWalkEvent';
8	import type { GraphWalkRouteContext } from '../GraphWalkOptions';
9	import { GraphWalkPhase as Phase } from '../GraphWalkPhase';
10	import type {
11	  GraphWalkVertex,
12	  GraphWalkVertexResult,
13	} from '../GraphWalkSource';
14	import type { GraphWalkInspection } from './GraphWalkInspection';
15	import type { GraphWalkOutcome, GraphWalkSummary } from './GraphWalkSummary';
16	import type {
17	  GraphWalkResolvedOptions,
18	  WalkVisitor,
19	} from './normalizeWalkOptions';
20	import type { WalkAction } from './WalkEffects';
21	import type { GraphWalkOperation } from '../GraphWalkOperation';
22	import type { WalkRoute } from './WalkFrontier';
23	import { projectPath, routeContains, WalkFrontier } from './WalkFrontier';
24	import { WalkResources } from './WalkResources';
25	import type { WalkCursor, WalkTarget } from './WalkSourceCache';
26	import {
27	  copyResolution,
28	  makeCursor,
29	  pullCursor,
30	  readStep,
31	  WalkSourceCache,
32	} from './WalkSourceCache';
33	import { WalkVisitorChain } from './WalkVisitorChain';
34	
35	const phases = [Phase.VERTEX, Phase.EDGE, Phase.PATH];
36	type Observation<Data, Edge, ID> = Extract<
37	  WalkAction<Data, Edge, ID>,
38	  { kind: 'OBSERVATION' }
39	> & { admissionIndex: number; vertexToken: symbol };
40	type Request<Data, Edge, ID> = Extract<
41	  WalkAction<Data, Edge, ID>,
42	  { kind: 'CALL' }
43	> & {
44	  issued: boolean;
45	  accept: (value: unknown) => void;
46	};
47	type Candidate<Data, Edge, ID> = {
48	  target: WalkTarget<ID>;
49	  parent: WalkRoute<Data, Edge, ID> | null;
50	  via: GraphWalkEdge<Edge, ID> | null;
51	};
52	
53	/** Promise-free transition owner. Only CALL closures perform source I/O. */
54	export class WalkKernel<Data, Edge, ID> {
55	  private readonly resources = new WalkResources();
56	  private readonly vertexTokens = new Map<ID, symbol>();
57	  private tornDown = false;
58	  private status = Status.INITIAL;
59	  private pauseRequested = false;
60	  private outcome: GraphWalkOutcome | null = null;
61	  private request: Request<Data, Edge, ID> | null = null;
62	  private requestId = 0;
63	  private boundaryId = 0;
64	  private roots: WalkCursor | null = null;
65	  private readonly rootIds = new Set<ID>();
66	  private readonly cache: WalkSourceCache<Data, Edge, ID>;
67	  private readonly frontier: WalkFrontier<Data, Edge, ID>;
68	  private readonly observations: Observation<Data, Edge, ID>[] = [];
69	  private chain: WalkVisitorChain<Data, Edge, ID> | null = null;
70	  private expansion: WalkRoute<Data, Edge, ID> | null = null;
71	  private depthLimited = false;
72	  private counts = {
73	    candidateReadAttempts: 0,
74	    admittedTargets: 0,
75	    uniqueFoundVertices: 0,
76	    uniqueOmittedVertices: 0,
77	    discoveredLinks: 0,
78	    processedObservations: {
79	      [Phase.VERTEX]: 0,
80	      [Phase.EDGE]: 0,
81	      [Phase.PATH]: 0,
82	    },
83	  };
84	  private execution;
85	
86	  constructor(
87	    private readonly options: GraphWalkResolvedOptions<Data, Edge, ID>,
88	    private readonly executionKind: 'sync' | 'async' = 'sync',
89	  ) {
90	    this.cache = new WalkSourceCache(options.source.hydration);
91	    this.frontier = new WalkFrontier(options.strategy);
92	    this.execution = options.execution;
93	  }
94	  getStatus(): Status {
95	    return this.status;
96	  }
97	  getStopReason(): TraversalStopReason | null {
98	    if (this.status === Status.HALTED) return 'paused';
99	    if (this.status === Status.FINISHED) return 'finished';
100	    if (this.status === Status.FAILED) return 'failed';
101	    return null;
102	  }
103	  isHalted(): boolean {
104	    return this.status === Status.HALTED;
105	  }
106	  requestPause(): boolean {
107	    if (this.status !== Status.RUNNING || this.pauseRequested) return false;
108	    this.pauseRequested = true;
109	    return true;
110	  }
111	  resume(config?: TraversalIterableConfigInput<Phase>): void {
112	    const execution = normalizeTraversalExecutionOptions(
113	      phases,
114	      config,
115	      this.execution,
116	    );
117	    this.execution = execution;
118	    if (this.status !== Status.FINISHED && this.status !== Status.FAILED) {
119	      this.status = Status.RUNNING;
120	      this.pauseRequested = false;
121	      this.chain?.resume();
122	    }
123	  }
124	  beginClose(): void {
125	    if (this.status === Status.FAILED || this.status === Status.FINISHED)
126	      return;
127	    this.status = Status.FINISHED;
128	    this.outcome = { kind: 'closed' };
129	  }
130	  shouldEmit(phase: Phase): boolean {
131	    return this.execution.emitEvents.includes(phase);
132	  }
133	
134	  private call(
135	    operation: GraphWalkOperation,
136	    invoke: () => unknown,
137	    accept: (value: unknown) => void,
138	    vertexToken?: symbol,
139	  ): void {
140	    this.request = {
141	      kind: 'CALL',
142	      requestId: this.requestId++,
143	      operation,
144	      vertexToken,
145	      invoke,
146	      accept,
147	      issued: false,
148	    };
149	  }
150	  submit(requestId: number, outcome: Outcome<unknown>): void {
151	    const request = this.request;
152	    if (request === null || request.requestId !== requestId || !request.issued)
153	      throw new Error('Invalid walking request settlement');
154	    this.request = null;
155	    try {
156	      if (!outcome.ok) throw outcome.error;
157	      request.accept(outcome.value);
158	    } catch (error) {
159	      if (this.outcome?.kind !== 'failed') {
160	        this.status = Status.FAILED;
161	        this.outcome = { kind: 'failed', error };
162	      }
163	    }
164	  }
165	  acknowledgeObservation(boundaryId: number): void {
166	    const observation = this.observations[0];
167	    if (observation === undefined || observation.boundaryId !== boundaryId)
168	      throw new Error('Invalid walking observation acknowledgement');
169	    this.counts.processedObservations[observation.phase]++;
170	    this.observations.shift();
171	    this.chain = null;
172	  }
173	  private token(vertexId: ID): symbol {
174	    let token = this.vertexTokens.get(vertexId);
175	    if (token === undefined) {
176	      token = Symbol('walking vertex');
177	      this.vertexTokens.set(vertexId, token);
178	    }
179	    return token;
180	  }
181	  private observe(
182	    phase: Phase,
183	    event: () => GraphWalkEvent<Data, Edge, ID>,
184	    vertexId: ID,
185	  ): void {
186	    this.observations.push({
187	      kind: 'OBSERVATION',
188	      phase,
189	      vertexToken: this.token(vertexId),
190	      admissionIndex: this.counts.admittedTargets - 1,
191	      boundaryId: this.boundaryId++,
192	      event,
193	    });
194	  }
195	
196	  private admit(candidate: Candidate<Data, Edge, ID>): void {
197	    this.counts.admittedTargets++;
198	    const { target } = candidate;
199	    if (this.cache.resolutions.has(target.vertexId)) {
200	      this.commit(
201	        candidate,
202	        this.cache.resolutions.get(target.vertexId)!,
203	        false,
204	      );
205	    } else if (target.resolution !== undefined) {
206	      this.commit(candidate, copyResolution<Data>(target.resolution), true);
207	    } else {
208	      const source = this.options.source;
209	      const resolveVertex = source.resolveVertex;
210	      if (resolveVertex === undefined)
211	        throw new TypeError('Cached walking target has no admitted resolution');
212	      this.call(
213	        'resolveVertex',
214	        () => resolveVertex.call(source.receiver, target.vertexId),
215	        (value) => this.commit(candidate, copyResolution<Data>(value), true),
216	        this.token(target.vertexId),
217	      );
218	    }
219	  }
220	  private commit(
221	    candidate: Candidate<Data, Edge, ID>,
222	    result: GraphWalkVertexResult<Data>,
223	    fresh: boolean,
224	  ): void {
225	    const { target, parent, via } = candidate;
226	    if (fresh) {
227	      this.cache.resolutions.set(target.vertexId, result);
228	      if (result.kind === 'found') this.counts.uniqueFoundVertices++;
229	      else this.counts.uniqueOmittedVertices++;
230	    }
231	    const vertex: GraphWalkVertex<Data, ID> | null =
232	      result.kind === 'found'
233	        ? { vertexId: target.vertexId, data: result.data }
234	        : null;
235	    const depth = parent === null ? 0 : parent.depth + 1;
236	    if (via !== null) {
237	      const source = parent!.vertex;
238	      this.observe(
239	        Phase.EDGE,
240	        () => ({
241	          kind: 'edge',
242	          edge: { ...via },
243	          fromVertex: { ...source },
244	          depth,
245	          target:
246	            vertex === null
247	              ? { kind: 'omitted' }
248	              : { kind: 'found', vertex: { ...vertex } },
249	        }),
250	        target.vertexId,
251	      );
252	    }
253	    if ((fresh || this.options.revisit !== 'once') && vertex !== null) {
254	      const route = { vertex, depth, via, parent };
255	      this.observe(
256	        Phase.VERTEX,
257	        () => ({
258	          kind: 'vertex',
259	          vertex: { ...vertex },
260	          depth,
261	          via: via === null ? null : { ...via },
262	        }),
263	        target.vertexId,
264	      );
265	      this.observe(Phase.PATH, () => projectPath(route), target.vertexId);
266	      this.expansion = route;
267	    }
268	  }
269	
270	  private booleanResult(value: unknown): boolean {
271	    if (typeof value !== 'boolean')
272	      throw new TypeError('Walking predicates must return booleans');
273	    return value;
274	  }
275	
276	  private routeContext(
277	    route: WalkRoute<Data, Edge, ID>,
278	  ): GraphWalkRouteContext<Data, Edge, ID> {
279	    const revisit = this.options.revisit;
280	    return revisit === 'once'
281	      ? { revisit }
282	      : { revisit, path: projectPath(route) };
283	  }
284	
285	  private follow(candidate: Candidate<Data, Edge, ID>): void {
286	    if (
287	      this.options.revisit === 'simplePaths' &&
288	      routeContains(candidate.parent!, candidate.target.vertexId)
289	    )
290	      return;
291	    const predicate = this.options.shouldFollowEdge;
292	    if (predicate === undefined) this.admit(candidate);
293	    else {
294	      this.call(
295	        'shouldFollowEdge',
296	        () =>
297	          predicate(
298	            { ...candidate.via! },
299	            {
300	              ...this.routeContext(candidate.parent!),
301	              fromVertex: { ...candidate.parent!.vertex },
302	              depth: candidate.parent!.depth + 1,
303	            },
304	          ),
305	        (value) => {
306	          if (this.booleanResult(value)) this.admit(candidate);
307	        },
308	        this.token(candidate.target.vertexId),
309	      );
310	    }
311	  }
312	
313	  private expand(route: WalkRoute<Data, Edge, ID>): void {
314	    const accept = (expand: boolean) => {
315	      if (!expand) return;
316	      const maxDepth = this.options.limits.maxDepth;
317	      if (maxDepth !== undefined && route.depth >= maxDepth)
318	        this.depthLimited = true;
319	      else this.frontier.push(route);
320	    };
321	    const predicate = this.options.shouldExpandVertex;
322	    if (predicate === undefined) accept(true);
323	    else {
324	      this.call(
325	        'shouldExpandVertex',
326	        () =>
327	          predicate(
328	            { ...route.vertex },
329	            {
330	              ...this.routeContext(route),
331	              depth: route.depth,
332	              via: route.via === null ? null : { ...route.via },
333	            },
334	          ),
335	        (value) => accept(this.booleanResult(value)),
336	        this.token(route.vertex.vertexId),
337	      );
338	    }
339	  }
340	
341	  /** Pure completion checks run before this gate; no exhaustion probing. */
342	  private limitBeforePull(): boolean {
343	    const { maxAdmittedTargets, maxCandidateReadAttempts } =
344	      this.options.limits;
345	    const admissionLimitReached =
346	      maxAdmittedTargets !== undefined &&
347	      this.counts.admittedTargets >= maxAdmittedTargets;
348	    const readLimitReached =
349	      maxCandidateReadAttempts !== undefined &&
350	      this.counts.candidateReadAttempts >= maxCandidateReadAttempts;
351	    if (!admissionLimitReached && !readLimitReached) return false;
352	    this.finish(admissionLimitReached, readLimitReached);
353	    return true;
354	  }
355	
356	  private finish(
357	    admissionLimitReached = false,
358	    readLimitReached = false,
359	  ): void {
360	    const reasons: (
361	      | 'maxDepth'
362	      | 'maxAdmittedTargets'
363	      | 'maxCandidateReadAttempts'
364	    )[] = [];
365	    if (this.depthLimited) reasons.push('maxDepth');
366	    if (admissionLimitReached) reasons.push('maxAdmittedTargets');
367	    if (readLimitReached) reasons.push('maxCandidateReadAttempts');
368	    this.status = Status.FINISHED;
369	    this.outcome =
370	      reasons.length > 0 ? { kind: 'limited', reasons } : { kind: 'exhausted' };
371	  }
372	
373	  poll(retainObservation = false): WalkAction<Data, Edge, ID> {
374	    for (;;) {
375	      if (this.request !== null && this.request.issued) return { kind: 'WAIT' };
376	      if (this.outcome !== null) {
377	        if (!this.tornDown) {
378	          this.tornDown = true;
379	          this.request = null;
380	          this.pauseRequested = false;
381	          this.observations.length = 0;
382	          this.chain = null;
383	          this.expansion = null;
384	          this.frontier.clear();
385	          this.rootIds.clear();
386	          this.vertexTokens.clear();
387	          this.cache.resolutions.clear();
388	          this.cache.adjacency.clear();
389	          this.roots = null;
390	        }
391	        const resource = this.resources.takeLast();
392	        if (resource !== undefined) {
393	          this.call(
394	            'iteratorReturn',
395	            () => {
396	              const close: (() => unknown) | undefined =
397	                resource.iterator.return;
398	              return close == null ? undefined : close.call(resource.iterator);
399	            },
400	            () => undefined,
401	            resource.vertexToken,
402	          );
403	          const request = this.request!;
404	          request.issued = true;
405	          const { kind, requestId, operation, invoke, vertexToken } = request;
406	          return { kind, requestId, operation, invoke, vertexToken };
407	        }
408	        return this.outcome.kind === 'failed'
409	          ? { kind: 'FAILED', error: this.outcome.error }
410	          : { kind: 'FINISHED' };
411	      }
412	      if (this.status === Status.HALTED) return { kind: 'HALTED' };
413	      if (this.status === Status.INITIAL) return { kind: 'WAIT' };
414	      // An admitted callback chain drains on cooperative pause. HALT keeps the
415	      // same chain at its next callback until a new execution lease resumes it.
416	      if (this.chain !== null) {
417	        const chain = this.chain;
418	        if (
419	          chain.paused ||
420	          (chain.done && retainObservation && this.pauseRequested)
421	        ) {
422	          this.status = Status.HALTED;
423	          return { kind: 'HALTED' };
424	        }
425	        if (chain.done) return this.observations[0]!;
426	        this.call(
427	          'visit',
428	          () => chain.invoke(),
429	          (value) => chain.submit(value),
430	          this.observations[0]!.vertexToken,
431	        );
432	      } else if (this.pauseRequested) {
433	        this.status = Status.HALTED;
434	        return { kind: 'HALTED' };
435	      }
436	      if (this.request !== null) {
437	        this.request.issued = true;
438	        const { kind, requestId, operation, invoke, vertexToken } =
439	          this.request;
440	        return { kind, requestId, operation, invoke, vertexToken };
441	      }
442	      if (this.observations.length > 0) {
443	        const observation = this.observations[0]!;
444	        const {
445	          enableVisitorFunctionsFor: include,
446	          disableVisitorFunctionsFor: exclude,
447	        } = this.execution;
448	        const enabled =
449	          include !== null
450	            ? include.includes(observation.phase)
451	            : exclude === null || !exclude.includes(observation.phase);
452	        // The phase-keyed records and projection originate at the same boundary.
453	        const records = enabled
454	          ? (this.options.visitors[observation.phase] as VisitorRecord<
455	              WalkVisitor<Data, Edge, Phase, ID>
456	            >[])
457	          : [];
458	        this.chain = new WalkVisitorChain(
459	          records,
460	          observation.phase,
461	          observation.event,
462	          observation.admissionIndex,
463	          this.counts.processedObservations[observation.phase],
464	        );
465	        continue;
466	      }
467	      if (this.expansion !== null) {
468	        const route = this.expansion;
469	        this.expansion = null;
470	        this.expand(route);
471	        continue;
472	      }
473	      const source = this.options.source;
474	      if (this.roots === null) {
475	        if (this.limitBeforePull()) continue;
476	        this.call(
477	          'roots',
478	          () => source.roots.call(source.receiver),
479	          (value) => {
480	            this.roots = makeCursor(value);
481	          },
482	        );
483	      } else if (
484	        !this.roots.done &&
485	        (this.options.strategy === 'breadthFirst' || this.frontier.size === 0)
486	      ) {
487	        if (this.limitBeforePull()) continue;
488	        const roots = this.roots;
489	        this.counts.candidateReadAttempts++;
490	        this.call(
491	          'rootNext',
492	          () => pullCursor(roots, this.executionKind, this.resources),
493	          (value) => {
494	            const step = readStep(value);
495	            if (step.done) {
496	              roots.done = true;
497	              this.resources.exhausted(roots.iterator!);
498	            } else {
499	              const target = this.cache.copyTarget(step.value);
500	              if (!this.rootIds.has(target.vertexId)) {
501	                this.rootIds.add(target.vertexId);
502	                this.admit({ target, parent: null, via: null });
503	              }
504	            }
505	          },
506	        );
507	      } else if (this.frontier.size > 0) {
508	        const frame = this.frontier.peek();
509	        const { route } = frame;
510	        const entries = this.cache.entries(route.vertex.vertexId);
511	        if (entries.cursor === null) {
512	          if (this.limitBeforePull()) continue;
513	          this.call(
514	            'outgoing',
515	            () => source.outgoing.call(source.receiver, { ...route.vertex }),
516	            (value) => {
517	              entries.cursor = makeCursor(value);
518	            },
519	            this.token(route.vertex.vertexId),
520	          );
521	        } else {
522	          if (this.limitBeforePull()) continue;
523	          const cursor = entries.cursor;
524	          const cached = frame.index < entries.links.length || cursor.done;
525	          this.counts.candidateReadAttempts++;
526	          this.call(
527	            'edgeNext',
528	            () =>
529	              cached
530	                ? frame.index < entries.links.length
531	                  ? { done: false, value: entries.links[frame.index] }
532	                  : { done: true }
533	                : pullCursor(
534	                    cursor,
535	                    this.executionKind,
536	                    this.resources,
537	                    this.token(route.vertex.vertexId),
538	                  ),
539	            (value) => {
540	              const step = readStep(value);
541	              if (step.done) {
542	                if (!cached) {
543	                  cursor.done = true;
544	                  this.resources.exhausted(cursor.iterator!);
545	                }
546	                this.frontier.remove();
547	              } else {
548	                const link = cached
549	                  ? entries.links[frame.index]!
550	                  : this.cache.copyLink(step.value);
551	                const index = frame.index++;
552	                if (!cached) {
553	                  entries.links.push(link);
554	                  this.counts.discoveredLinks++;
555	                }
556	                this.follow({
557	                  target: link.target,
558	                  parent: route,
559	                  via: {
560	                    from: route.vertex.vertexId,
561	                    outgoingIndex: index,
562	                    to: link.target.vertexId,
563	                    data: link.data,
564	                  },
565	                });
566	              }
567	            },
568	            this.token(route.vertex.vertexId),
569	          );
570	        }
571	      } else {
572	        this.finish();
573	      }
574	    }
575	  }
576	  summary(): GraphWalkSummary {
577	    return Object.freeze({
578	      status: this.status,
579	      counts: Object.freeze({
580	        ...this.counts,
581	        processedObservations: Object.freeze({
582	          ...this.counts.processedObservations,
583	        }),
584	      }),
585	      outcome:
586	        this.outcome === null
587	          ? null
588	          : this.outcome.kind === 'limited'
589	          ? Object.freeze({
590	              ...this.outcome,
591	              reasons: Object.freeze([...this.outcome.reasons]),
592	            })
593	          : Object.freeze({ ...this.outcome }),
594	    });
595	  }
596	  inspect(): GraphWalkInspection {
597	    const { emitEvents, visitorPhases } = normalizeTraversalExecutionOptions(
598	      phases,
599	      undefined,
600	      this.execution,
601	    );
602	    const execution = { emitEvents, visitorPhases };
603	    Object.freeze(execution.emitEvents);
604	    if (execution.visitorPhases !== 'all') {
605	      if ('include' in execution.visitorPhases)
606	        Object.freeze(execution.visitorPhases.include);
607	      else Object.freeze(execution.visitorPhases.exclude);
608	      Object.freeze(execution.visitorPhases);
609	    }
610	    const counts = this.summary().counts;
611	    Object.freeze(counts.processedObservations);
612	    return Object.freeze({
613	      kind: 'graph-walk',
614	      sourceMode: 'graph',
615	      concurrency: 1,
616	      status: this.status,
617	      stopReason: this.getStopReason(),
618	      pauseRequested: this.pauseRequested,
619	      execution: this.executionKind,
620	      strategy: this.options.strategy,
621	      revisit: this.options.revisit,
622	      executionOptions: Object.freeze(execution),
623	      counts: Object.freeze(counts),
624	      frontierSize: this.frontier.size,
625	      // A taken resource remains open until its return request settles.
626	      openSourceIteratorCount:
627	        this.resources.size +
628	        (this.request?.operation === 'iteratorReturn' ? 1 : 0),
629	      pendingObservationKinds: Object.freeze(
630	        this.observations.map((item) => item.phase),
631	      ),
632	      activeVisitor:
633	        this.chain === null
634	          ? null
635	          : Object.freeze({
636	              phase: this.chain.phase,
637	              visitorIndex: this.chain.visitorIndex,
638	            }),
639	      pendingRequests: Object.freeze(
640	        this.request === null
641	          ? []
642	          : [
643	              Object.freeze({
644	                requestId: this.request.requestId,
645	                operation: this.request.operation,
646	                vertexToken: this.request.vertexToken,
647	              }),
648	            ],
649	      ),
650	      inFlightCallbackCount:
651	        this.request !== null && this.request.issued ? 1 : 0,
652	      bufferedEventCount: this.observations.length,
