1	import {
2	  vertexHandle,
3	  internalRef,
4	  resolutionContextView,
5	  resolvedGraphView,
6	} from './observationFacets';
7	import type { VertexHandle } from './CTTRef';
8	import type { ResolvedGraphView } from './ResolvedGraphView';
9	import { normalizePathOptions } from '@core/normalizePathOptions';
10	import type { VertexTypes } from '@core/TreeTypeParameters';
11	import type { Vertex } from '@core/Vertex';
12	import type { MutableRef } from '@core/CTTRef';
13	import type { TreeSource, TreeVertexResolution } from '@core/TraversableTree';
14	import type { ResolvedTreeVertexTypes } from '@core/ResolvedTreeVertexTypes';
15	import type { ResolvedTreeView } from '@core/ResolvedTreeView';
16	import { GraphStore } from '@core/graph/GraphStore';
17	import { registerTreeGraphStore } from '@core/graph/treeStoreCapabilities';
18	import { jsonStringifySafe } from '@utils/jsonStringifySafe';
19	
20	export type InternalVertexResolutionContext<TTP extends VertexTypes> = {
21	  depth: number;
22	  parentVertex: Vertex<TTP>;
23	  parentVertexRef: MutableRef<Vertex<TTP>>;
24	  hintIndex: number;
25	  vertexHint: TTP['VertexHint'];
26	};
27	
28	export type TreeVertexMetadata<TTP extends VertexTypes> = {
29	  resolutionContext: InternalVertexResolutionContext<TTP> | null;
30	};
31	
32	export type TreeVertexRecordContent<TTP extends VertexTypes> = {
33	  metadata: TreeVertexMetadata<TTP>;
34	  children: MutableRef<Vertex<TTP>>[];
35	};
36	
37	export class TreeVertexRecord<TTP extends VertexTypes>
38	  implements TreeVertexRecordContent<TTP>
39	{
40	  readonly metadata: TreeVertexMetadata<TTP>;
41	  readonly children: MutableRef<Vertex<TTP>>[];
42	
43	  constructor(vertexContent: TreeVertexRecordContent<TTP>) {
44	    this.metadata = vertexContent.metadata;
45	    this.children = vertexContent.children;
46	  }
47	
48	  pushChildren(children: Array<MutableRef<Vertex<TTP>>>): void {
49	    for (const child of children) {
50	      this.children.push(child);
51	    }
52	  }
53	
54	  getResolutionContext(): InternalVertexResolutionContext<TTP> | null {
55	    return this.metadata.resolutionContext;
56	  }
57	
58	  setResolutionContext(
59	    resolutionContext: InternalVertexResolutionContext<TTP> | null,
60	  ): void {
61	    this.metadata.resolutionContext = resolutionContext;
62	  }
63	
64	  getChildren(): MutableRef<Vertex<TTP>>[] {
65	    return this.children;
66	  }
67	
68	  getParent(): MutableRef<Vertex<TTP>> | null {
69	    return this.metadata.resolutionContext?.parentVertexRef ?? null;
70	  }
71	
72	  clone(
73	    content?: Partial<TreeVertexRecordContent<TTP>>,
74	  ): TreeVertexRecord<TTP> {
75	    const data = content?.metadata ?? this.metadata;
76	    const children = content?.children ?? this.children;
77	    return new TreeVertexRecord<TTP>({
78	      metadata: {
79	        ...data,
80	        resolutionContext:
81	          data.resolutionContext === null
82	            ? null
83	            : { ...data.resolutionContext },
84	      },
85	      children: children.slice(),
86	    });
87	  }
88	}
89	
90	export type ResolvedTreeMap<TTP extends VertexTypes> = Map<
91	  MutableRef<Vertex<TTP>>,
92	  TreeVertexRecord<TTP>
93	>;
94	
95	export type GetPathToOptions = {
96	  noRoot?: boolean | undefined;
97	  noSelf?: boolean | undefined;
98	};
99	
100	export class ResolvedTreeStore<TTP extends VertexTypes>
101	  implements TreeSource<ResolvedTreeVertexTypes<TTP>>
102	{
103	  private readonly store: GraphStore<TTP>;
104	  private readonly readOnly: ResolvedTreeView<TTP>;
105	
106	  constructor(/*config: ResolvedTreeConfig<TTP, RW_TTP>*/) {
107	    this.store = new GraphStore<TTP>('tree');
108	    registerTreeGraphStore(this, this.store);
109	    this.readOnly = Object.freeze({
110	      getRoot: () => vertexHandle(this.getRoot()),
111	      has: (ref: VertexHandle<TTP>) => this.has(internalRef(ref)),
112	      getChildrenOf: (ref: VertexHandle<TTP>) => {
113	        const children = this.getChildrenOf(internalRef(ref));
114	        return children === null
115	          ? null
116	          : Object.freeze(children.map((child) => vertexHandle(child)));
117	      },
118	      getParentOf: (ref: VertexHandle<TTP>) =>
119	        vertexHandle(this.getParentOf(internalRef(ref))),
120	      requirePathTo: (ref: VertexHandle<TTP>, options?: GetPathToOptions) =>
121	        Object.freeze(
122	          this.requirePathTo(internalRef(ref), options).map((item) =>
123	            vertexHandle(item),
124	          ),
125	        ),
126	      getResolutionContextOf: (ref: VertexHandle<TTP>) =>
127	        resolutionContextView(
128	          this.get(internalRef(ref))?.getResolutionContext() ?? null,
129	        ),
130	    });
131	  }
132	
133	  /** A stable live facade without editing methods or mutable records. */
134	  asReadOnly(): ResolvedTreeView<TTP> {
135	    return this.readOnly;
136	  }
137	
138	  getRoot(): MutableRef<Vertex<TTP>> | null {
139	    return this.store.graph.getRoot();
140	  }
141	
142	  setRoot(root: MutableRef<Vertex<TTP>>): void {
143	    this.store.setRoot(root);
144	  }
145	
146	  getResolvedGraphView(): ResolvedGraphView<TTP> {
147	    return resolvedGraphView(this.store.graph);
148	  }
149	
150	  getChildrenOf(
151	    vertexRef: MutableRef<Vertex<TTP>>,
152	  ): Array<MutableRef<Vertex<TTP>>> | null {
153	    return this.get(vertexRef)?.getChildren().slice() ?? null;
154	  }
155	
156	  getParentOf(
157	    vertexRef: MutableRef<Vertex<TTP>>,
158	  ): MutableRef<Vertex<TTP>> | null {
159	    return this.get(vertexRef)?.getParent() ?? null;
160	  }
161	
162	  private deleteChildOf(
163	    parent: MutableRef<Vertex<TTP>>,
164	    child: MutableRef<Vertex<TTP>>,
165	  ): void {
166	    const resolved = this.get(parent);
167	    if (resolved !== null) {
168	      const newResolved = resolved.clone({
169	        children: resolved.getChildren().filter((c) => c !== child),
170	      });
171	      this.set(parent, newResolved);
172	    }
173	  }
174	
175	  deleteSubtree(vertexRef: MutableRef<Vertex<TTP>>): void {
176	    const parent = this.getParentOf(vertexRef);
177	    if (parent !== null) {
178	      this.deleteChildOf(parent, vertexRef);
179	    }
180	
181	    const refsToDelete = [vertexRef];
182	    const visited = new Set<MutableRef<Vertex<TTP>>>();
183	    while (refsToDelete.length > 0) {
184	      const currentRef = refsToDelete.pop();
185	      if (currentRef === undefined || visited.has(currentRef)) {
186	        continue;
187	      }
188	      visited.add(currentRef);
189	      const currentResolved = this.get(currentRef);
190	      if (currentResolved !== null) {
191	        for (const childRef of currentResolved.getChildren()) {
192	          refsToDelete.push(childRef);
193	        }
194	      }
195	    }
196	    this.store.removeVertices(visited);
197	  }
198	
199	  has(vertexRef: MutableRef<Vertex<TTP>>): boolean {
200	    return this.store.graph.has(vertexRef);
201	  }
202	
203	  get(vertexRef: MutableRef<Vertex<TTP>>): TreeVertexRecord<TTP> | null {
204	    return this.store.getTreeRecord(vertexRef);
205	  }
206	
207	  set(
208	    vertexRef: MutableRef<Vertex<TTP>>,
209	    vertexResolved: TreeVertexRecord<TTP>,
210	  ): void {
211	    this.store.setTreeRecord(vertexRef, vertexResolved);
212	  }
213	
214	  getResolutionContextOf(
215	    vertexRef: MutableRef<Vertex<TTP>>,
216	  ): InternalVertexResolutionContext<TTP> | null {
217	    const context = this.get(vertexRef)?.getResolutionContext() ?? null;
218	    return context === null ? null : { ...context };
219	  }
220	
221	  pushChildrenTo(
222	    vertexRef: MutableRef<Vertex<TTP>>,
223	    children: Array<MutableRef<Vertex<TTP>>>,
224	  ): void {
225	    const parentVertexResolved = this.get(vertexRef);
226	    if (parentVertexResolved == null) {
227	      throw new Error(`Could not find ref - ${jsonStringifySafe(vertexRef)}`);
228	    }
229	    parentVertexResolved.pushChildren(children);
230	  }
231	
232	  requirePathTo(
233	    vertexRef: MutableRef<Vertex<TTP>>,
234	    options?: GetPathToOptions,
235	  ): MutableRef<Vertex<TTP>>[] {
236	    const pathOptions = normalizePathOptions(options);
237	    if (!this.has(vertexRef)) {
238	      throw new Error(`Could not find ref - ${jsonStringifySafe(vertexRef)}`);
239	    }
240	    let curVertex = vertexRef;
241	    const reversedPath: MutableRef<Vertex<TTP>>[] = [curVertex];
242	    while (true) {
243	      const parent = this.getParentOf(curVertex);
244	      if (parent === null) {
245	        break;
246	      } else {
247	        reversedPath.push(parent);
248	        curVertex = parent;
249	      }
250	    }
251	    let straightPath = reversedPath.reverse();
252	    if (pathOptions.noRoot === true && straightPath[0] === this.getRoot()) {
253	      straightPath = straightPath.slice(1);
254	    }
255	    if (
256	      pathOptions.noSelf === true &&
257	      straightPath[straightPath.length - 1] === vertexRef
258	    ) {
259	      straightPath = straightPath.slice(0, -1);
260	    }
261	    return straightPath;
262	  }
263	
264	  resolveRoot(): TreeVertexResolution<ResolvedTreeVertexTypes<TTP>> {
265	    const root = this.getRoot();
266	    if (root === null) {
267	      return { kind: 'omitted' };
268	    }
269	    return {
270	      kind: 'found',
271	      vertex: {
272	        vertexContent: {
273	          $data: root,
274	          $childHints: this.getChildrenOf(root) ?? [],
275	        },
276	      },
277	    };
278	  }
279	
280	  resolveChild(
281	    vertexHint: ResolvedTreeVertexTypes<TTP>['VertexHint'],
282	  ): TreeVertexResolution<ResolvedTreeVertexTypes<TTP>> {
283	    return {
284	      kind: 'found',
285	      vertex: {
286	        vertexContent: {
287	          $data: vertexHint,
288	          $childHints: this.getChildrenOf(vertexHint) ?? [],
289	        },
290	      },
291	    };
292	  }
293	}
294	
295	/** Stable detached discovery metadata; all CTT references are restricted. */
296	export type VertexResolutionContext<T extends VertexTypes> = Readonly<{
297	  depth: number;
298	  parentVertex: import('./Vertex').VertexView<T>;
299	  parentVertexRef: import('./CTTRef').VertexHandle<T>;
300	  hintIndex: number;
301	  vertexHint: T['VertexHint'];
302	}>;
303

