2	import type {
3	  DagDefinition,
4	  DagDefinitionIssue,
5	  DagDefinitionSlot,
6	} from '../../traversals/dag-traversal/lib/DagDefinition';
7	
8	/** Check materialized membership and structural topology before source replay. */
9	export function validateDefinition<Data, ID>(
10	  definition: DagDefinition<Data, ID>,
11	): DagDefinitionIssue<ID>[] {
12	  const issues: DagDefinitionIssue<ID>[] = [];
13	  const byId = new Map(
14	    definition.vertices.map((vertex) => [vertex.vertexId, vertex]),
15	  );
16	  const omitted = new Set(definition.omittedIds);
17	  const invalidOmissions = new Set<ID>();
18	  const graph = new Map<ID, ID[]>();
19	  const queue: ID[] = [];
20	  const entry = definition.entry;
21	  if (entry.kind === 'root') {
22	    if (!byId.has(entry.vertexId))
23	      issues.push({
24	        kind: 'invalidEntry',
25	        reason: 'unknownRoot',
26	        vertexIds: [entry.vertexId],
27	      });
28	    queue.push(entry.vertexId);
29	  } else if (entry.kind === 'empty') {
30	    if (definition.vertices.length > 0)
31	      issues.push({
32	        kind: 'invalidEntry',
33	        reason: 'emptyWithVertices',
34	        vertexIds: definition.vertices.map((vertex) => vertex.vertexId),
35	      });
36	    for (const id of definition.omittedIds) queue.push(id);
37	  } else if (
38	    entry.slots.some(
39	      (slot) => slot.kind === 'omitted' && slot.identity === null,
40	    )
41	  ) {
42	    issues.push({
43	      kind: 'invalidEntry',
44	      reason: 'anonymousCatalogEntry',
45	      vertexIds: [],
46	    });
47	  }
48	  const slotIds = (slots: readonly DagDefinitionSlot<ID>[]): ID[] => {
49	    const result: ID[] = [];
50	    for (const slot of slots) {
51	      if (slot.kind === 'vertex') result.push(slot.vertexId);
52	      else if (slot.identity !== null) result.push(slot.identity.vertexId);
53	    }
54	    return result;
55	  };
56	  const checkSlots = (
57	    slots: readonly DagDefinitionSlot<ID>[],
58	    parent: { vertexId: ID } | null,
59	  ): ID[] => {
60	    const children: ID[] = [];
61	    for (const slot of slots) {
62	      if (slot.kind === 'vertex') {
63	        if (byId.has(slot.vertexId)) children.push(slot.vertexId);
64	        else
65	          issues.push({
66	            kind: 'missingStructuralEndpoint',
67	            parent,
68	            vertexId: slot.vertexId,
69	          });
