1	import type { TraversalExecutionState } from '@core/TraversalExecution';
2	import type { TreeDagExecutionInspection } from '@core/CoreInspection';
3	import type { DagVisitorPhase } from './lib/DagTraversalOrder';
4	import type { VertexTypes } from '@core/TreeTypeParameters';
5	import { inspectDagMilestones } from './inspectDag';
6	import type { AsyncDagTraversalRunner } from './lib/AsyncDagTraversalRunner';
7	import type { DagMilestoneSnapshot } from './lib/DagInspection';
8	import type {
9	  DagDeferredWork,
10	  DagSettlementOutcome,
11	  DagSummary,
12	} from './lib/DagProgress';
13	import { dagRunnerCapabilities } from './lib/dagRunnerCapabilities';
14	import type { DagTraversalRunner } from './lib/DagTraversalRunner';
15	
16	/** Declaration only: issued objects use WeakMap ownership, with no constructor value. */
17	declare class NominalDagWorkTicket<ID> {
18	  private constructor();
19	  private readonly ticketIdentity: never;
20	  readonly vertexId: ID;
21	}
22	
23	/** Local settlement capability issued by one coordinator; copying loses ownership. */
24	export type DagWorkTicket<ID = unknown> = NominalDagWorkTicket<ID>;
25	
26	export type DagWorkBoundary<ID = unknown> =
27	  | Readonly<{
28	      kind: 'awaitingSettlement';
29	      workTickets: readonly DagWorkTicket<ID>[];
30	    }>
31	  | Readonly<{ kind: 'paused' }>
32	  | Readonly<{ kind: 'finished' }>;
33	
34	export type DagSettlementReceipt =
35	  | Readonly<{ kind: 'accepted' }>
36	  | Readonly<{ kind: 'alreadyAccepted' }>;
37	
38	export interface DagWorkSessionControl<ID = unknown>
39	  extends TraversalExecutionState<TreeDagExecutionInspection<DagVisitorPhase>> {
40	  completeWork(ticket: DagWorkTicket<ID>): DagSettlementReceipt;
41	  /** Fatal for the whole traversal; keep retryable work deferred instead. */
42	  failTraversal(
43	    ticket: DagWorkTicket<ID>,
44	    error: unknown,
45	  ): DagSettlementReceipt;
46	  /** Capture dependency explanations without advancing the coordinated runner. */
47	  inspectMilestones(): DagMilestoneSnapshot<ID>;
48	  summary(): DagSummary<ID>;
49	  requestPause(): boolean;
50	}
51	
52	export interface DagWorkSession<ID = unknown>
53	  extends DagWorkSessionControl<ID> {
54	  advance(): DagWorkBoundary<ID>;
55	}
56	
57	export interface AsyncDagWorkSession<ID = unknown>
58	  extends DagWorkSessionControl<ID> {
59	  advance(): Promise<DagWorkBoundary<ID>>;
60	}
61	
62	type SettlementRunner<ID> = Pick<
63	  DagTraversalRunner<VertexTypes, VertexTypes, ID>,
64	  | 'settle'
65	  | 'summary'
66	  | 'requestPause'
67	  | 'getStopReason'
68	  | 'getStatus'
69	  | 'isHalted'
70	  | 'inspect'
71	>;
72	
73	function makeCoordination<ID>(
74	  runner: SettlementRunner<ID>,
75	  inspectDependencies: () => DagMilestoneSnapshot<ID>,
76	) {
77	  if (
78	    dagRunnerCapabilities.get(runner)?.workCompletion !== 'externalSettlement'
79	  ) {
80	    throw new TypeError(
81	      'DAG coordination requires externalSettlement work completion',
82	    );
83	  }
84	  const tickets = new WeakMap<DagWorkTicket<ID>, DagDeferredWork<ID>>();
85	  const settle = (
86	    ticket: DagWorkTicket<ID>,
87	    outcome: DagSettlementOutcome,
88	  ): DagSettlementReceipt => {
89	    const work = tickets.get(ticket);
90	    if (work === undefined) {
91	      throw new TypeError('Unknown or foreign DAG work ticket');
92	    }
93	    return {
94	      kind: runner.settle(work.vertexId, outcome, work.generation)
95	        ? 'accepted'
96	        : 'alreadyAccepted',
97	    };
98	  };
99	  const failTraversal = (ticket: DagWorkTicket<ID>, error: unknown) =>
100	    settle(ticket, { kind: 'traversalFailed', error });
101	  return {
102	    completeWork: (ticket: DagWorkTicket<ID>) =>
103	      settle(ticket, { kind: 'workCompleted' }),
104	    failTraversal,
105	    getStatus: () => runner.getStatus(),
106	    getStopReason: () => runner.getStopReason(),
107	    isHalted: () => runner.isHalted(),
108	    inspect: () => runner.inspect(),
109	    inspectMilestones: inspectDependencies,
110	    summary: () => runner.summary(),
111	    requestPause: () => runner.requestPause(),
112	    boundary: (): DagWorkBoundary<ID> => {
113	      const reason = runner.getStopReason();
114	      if (reason === 'finished') return { kind: 'finished' };
115	      if (reason === 'paused') return { kind: 'paused' };
116	      return {
117	        kind: 'awaitingSettlement',
118	        workTickets: runner.summary().awaitingSettlement.map((work) => {
119	          // The private WeakMap, not a copyable field, proves ticket ownership.
120	          const ticket = Object.freeze({
121	            vertexId: work.vertexId,
122	          }) as DagWorkTicket<ID>;
123	          tickets.set(ticket, work);
124	          return ticket;
125	        }),
126	      };
127	    },
128	  };
129	}
130	
131	/** Wrap an external-settlement runner without executing or acquiring it. */
132	export function bindDagWorkSession<
133	  T extends VertexTypes,
134	  R extends VertexTypes,
135	  ID,
136	>(runner: DagTraversalRunner<T, R, ID>): DagWorkSession<ID> {
137	  const { boundary, ...control } = makeCoordination(runner, () =>
138	    inspectDagMilestones(runner),
139	  );
140	  return {
141	    ...control,
142	    advance: () => {
143	      runner.run();
144	      return boundary();
145	    },
146	  };
147	}
148	
149	/** Async execution uses the runner's existing ownership and drain semantics. */
150	export function bindAsyncDagWorkSession<
151	  T extends VertexTypes,
152	  R extends VertexTypes,
153	  ID,
154	>(runner: AsyncDagTraversalRunner<T, R, ID>): AsyncDagWorkSession<ID> {
155	  const { boundary, ...control } = makeCoordination(runner, () =>
156	    inspectDagMilestones(runner),
157	  );
158	  return {
159	    ...control,
160	    advance: async () => {
161	      await runner.run();
162	      return boundary();
163	    },
164	  };
165	}
166

