120	    const progress = snapshot.summary.vertices.get(id)!;
121	    return {
122	      ...progress,
123	      unmetPrerequisiteIds: progress.unmetPrerequisiteIds.slice(),
124	      unmetWorkPrerequisiteIds: progress.unmetWorkPrerequisiteIds.slice(),
125	      unmetSubgraphPrerequisiteIds:
126	        progress.unmetSubgraphPrerequisiteIds.slice(),
127	    };
128	  };
