131	    const target = { vertexId: input.vertexId, milestone: input.milestone };
132	    const discoveryComplete = snapshot.state.discoveryComplete;
133	    const kind = identities.get(target.vertexId);
134	    if (kind === undefined || kind === 'deleted')
135	      return {
136	        kind: kind === undefined ? 'unresolved' : kind,
137	        target,
138	        discoveryComplete,
139	      };
140	    if (kind === 'omitted')
141	      return {
142	        kind: 'omitted',
143	        target,
144	        satisfied: true,
145	        progress: null,
146	        blockers: [],
147	        discoveryComplete,
148	      };
149	    const isSatisfied = satisfied(target);
150	    const blockers: DagBlocker<ID>[] = [];
151	    if (!isSatisfied) {
152	      // Start unsatisfied and admit only unmet endpoints: satisfied nodes never enter the queue.
153	      const reachable = walk(
154	        target,
155	        'prerequisites',
156	        true,
157	        (edge) => !satisfied(edge.prerequisite),
158	      );
159	      const blockedWork = new Set<ID>();
160	      for (const edge of reachable.edges) {
161	        blockers.push({
162	          ...edge,
163	          kind: 'constraint',
164	          waiterStatus: status(edge.waiter),
165	          prerequisiteStatus: status(edge.prerequisite),
166	        });
167	        if (edge.waiter.milestone === 'work')
168	          blockedWork.add(edge.waiter.vertexId);
169	      }
170	      for (const current of [target, ...reachable.milestones]) {
171	        const endpoint = status(current);
172	        if (endpoint.kind !== 'live') continue;
173	        if (current.milestone === 'work') {
174	          // Engine W state and initialCommitted agree; unsatisfied W cannot be completed.
175	          if (!blockedWork.has(current.vertexId))
176	            blockers.push({
177	              kind: 'unfinishedWork',
178	              target: { vertexId: current.vertexId, milestone: 'work' },
179	              work: endpoint.work as Exclude<DagWorkState, 'completed'>,
180	            });
