193	              kind: 'completionPending',
194	              target: {
195	                vertexId: current.vertexId,
196	                milestone: 'subgraphCompletion',
197	              },
198	            });
199	        }
200	      }
201	    }
202	    return {
203	      kind: 'live',
204	      target,
205	      satisfied: isSatisfied,
206	      progress: copyProgress(target.vertexId),
207	      blockers,
208	      discoveryComplete,
209	    };
210	  };
211	  const query = (
212	    input: DagMilestone<ID>,
213	    direction: 'prerequisites' | 'dependents',
214	    options: DagMilestoneQueryOptions = {},
215	  ): DagMilestoneQueryResult<ID> => {
216	    const target = { vertexId: input.vertexId, milestone: input.milestone };
217	    return {
218	      ...(identities.has(target.vertexId)
219	        ? walk(target, direction, options.transitive ?? false)
220	        : { milestones: [], edges: [] }),
221	      discoveryComplete: snapshot.state.discoveryComplete,
222	    };
223	  };
224	  return {
225	    explain,
226	    prerequisitesOf: (target, options) =>
227	      query(target, 'prerequisites', options),
228	    dependentsOf: (target, options) => query(target, 'dependents', options),
229	  };
230	}
