1	import type {
2	  MakeVertexResult,
3	  DagPrerequisiteResolution,
4	  TreeVertexResolution,
5	} from '@core/TraversableTree';
6	import type { VertexTypes } from '@core/TreeTypeParameters';
7	import type { MaybePromise } from '@core/graph/types';
8	
9	/** Validate before tagged branches can discard unsupported source fields. */
10	export function assertNoTreeMetadata(
11	  result: object,
12	  sourceName = 'Tree source',
13	): void {
14	  if (
15	    Object.prototype.hasOwnProperty.call(result, 'identity') ||
16	    Object.prototype.hasOwnProperty.call(result, 'vertexId') ||
17	    Object.prototype.hasOwnProperty.call(result, 'dependsOnWork') ||
18	    Object.prototype.hasOwnProperty.call(
19	      result,
20	      'dependsOnSubgraphCompletion',
21	    ) ||
22	    Object.prototype.hasOwnProperty.call(result, 'satisfiesDependencies')
23	  ) {
24	    throw new TypeError(`${sourceName} results cannot include graph metadata`);
25	  }
26	}
27	
28	/** Structural source types cannot distinguish own fields from prototype fields. */
29	function assertOwnGraphIdentity(result: object): void {
30	  if (
31	    'vertexId' in result &&
32	    !Object.prototype.hasOwnProperty.call(result, 'vertexId')
33	  ) {
34	    throw new TypeError('Graph source vertexId must be an own property');
35	  }
36	}
37	
38	/** Normalize adapter vocabulary before any scheduling or identity decisions. */
39	export function normalizeSourceResult<T extends VertexTypes, ID = unknown>(
40	  result: DagPrerequisiteResolution<T, ID> | TreeVertexResolution<T>,
41	  prerequisite: boolean,
42	  treeSourceName?: string,
43	): MakeVertexResult<T> | undefined {
44	  if (result === null || typeof result !== 'object') {
45	    throw new TypeError('Invalid source resolution result');
46	  }
47	  if (treeSourceName !== undefined)
48	    assertNoTreeMetadata(result, treeSourceName);
49	  else assertOwnGraphIdentity(result);
50	  if (!('kind' in result))
51	    throw new TypeError('Source results require a canonical kind tag');
52	  switch (result.kind) {
53	    case 'found': {
54	      const vertex = result.vertex;
55	      if (
56	        vertex === null ||
57	        typeof vertex !== 'object' ||
58	        vertex.vertexContent == null
59	      ) {
60	        throw new TypeError(
61	          'Found source result requires non-null vertexContent',
62	        );
63	      }
64	      if (treeSourceName !== undefined)
65	        assertNoTreeMetadata(vertex, treeSourceName);
66	      else assertOwnGraphIdentity(vertex);
67	      return vertex;
68	    }
69	    case 'omitted': {
70	      if (treeSourceName !== undefined) return { vertexContent: null };
71	      if (result.satisfiesDependencies !== true) {
72	        throw new TypeError(
73	          'Omitted source result requires satisfiesDependencies: true',
74	        );
75	      }
76	      if ('vertexId' in result || !('identity' in result)) {
77	        throw new TypeError(
78	          'Omitted source result requires explicit identity, not vertexId',
79	        );
80	      }
81	      const identity = result.identity;
82	      if (identity === null) return { vertexContent: null };
83	      if (
84	        typeof identity !== 'object' ||
85	        Array.isArray(identity) ||
86	        !Object.prototype.hasOwnProperty.call(identity, 'vertexId')
87	      ) {
88	        throw new TypeError(
89	          'Omission identity must be null or an own vertexId wrapper',
90	        );
91	      }
92	      return { vertexContent: null, vertexId: identity.vertexId };
93	    }
94	    case 'missing':
95	      if (!prerequisite) {
96	        throw new TypeError(
97	          'Missing source result is only valid for prerequisite lookup',
98	        );
99	      }
100	      return undefined;
101	    default:
102	      throw new TypeError('Invalid source resolution kind');
103	  }
104	}
105	
106	/** Preserve thenable transport, including throwing getters and calls. */
107	export function mapSourceResult<I, O>(
108	  result: MaybePromise<I>,
109	  normalize: (value: I) => O,
110	): MaybePromise<O> {
111	  let then: PromiseLike<I>['then'] | undefined;
112	  try {
113	    then = (result as PromiseLike<I>)?.then;
114	  } catch (error) {
115	    // Retain the first accessor failure while leaving diagnostics to transport.
116	    return {
117	      get then(): PromiseLike<O>['then'] {
118	        throw error;
119	      },
120	    };
121	  }
122	  if (typeof then !== 'function') return normalize(result as I);
123	  return {
124	    then(onfulfilled, onrejected) {
125	      return then!.call(
126	        result,
127	        (value) => {
128	          let normalized: O;
129	          try {
130	            normalized = normalize(value);
131	          } catch (error) {
132	            return onrejected!(error);
133	          }
134	          return onfulfilled!(normalized);
135	        },
136	        onrejected,
137	      );
138	    },
139	  } as PromiseLike<O>;
