    return Array.from(this.ids, ([vertexId, { kind }]) => ({ vertexId, kind }));
  }

  getTraversalSlots(
    ref: InternalVertexRef<T>,
  ): readonly InternalChildSlot<T>[] | null {
    return this.getEntry(ref).slots?.map((slot) => ({ ...slot })) ?? null;
  }

