1	import type { InternalResolvedGraphView } from '@core/ResolvedGraphView';
2	import type { VertexTypes } from '@core/TreeTypeParameters';
3	import type { InternalVertexRef } from '@core/graph/types';
4	
5	/** A forest view: the scheduler's root remains private structural bookkeeping. */
6	export function makeDagGraphView<T extends VertexTypes, ID = unknown>(
7	  graph: InternalResolvedGraphView<T, ID>,
8	  hiddenRoot: () => InternalVertexRef<T> | null,
9	): InternalResolvedGraphView<T, ID> {
10	  const visible = (ref: InternalVertexRef<T>) => ref !== hiddenRoot();
11	  const getVertexRefById = (id: ID) => {
12	    const ref = graph.getVertexRefById(id);
13	    return ref !== null && visible(ref) ? ref : null;
14	  };
15	  const requireVertexId = (ref: InternalVertexRef<T>) => {
16	    if (!visible(ref)) throw new Error('Unknown vertex reference');
17	    return graph.requireVertexId(ref);
18	  };
19	  return Object.freeze({
20	    get: (ref: InternalVertexRef<T>) => {
21	      const vertex = visible(ref) ? graph.get(ref) : null;
22	      return vertex === null
23	        ? null
24	        : Object.freeze({
25	            ...vertex,
26	            discoveryDepth: vertex.discoveryDepth - 1,
27	            incoming: Object.freeze(
28	              vertex.incoming.filter((edge) => visible(edge.parentRef)),
29	            ),
30	          });
31	    },
32	    has: (ref: InternalVertexRef<T>) => visible(ref) && graph.has(ref),
33	    getRoot: () => null,
34	    getVertexRefs: () => graph.getVertexRefs().filter(visible),
35	    getVertexRefById,
36	    requireVertexId,
37	    getVisitStageOf: (ref: InternalVertexRef<T>) =>
38	      visible(ref) ? graph.getVisitStageOf(ref) : null,
39	    getParentsOf: (ref: InternalVertexRef<T>) =>
40	      visible(ref) ? graph.getParentsOf(ref)?.filter(visible) ?? null : null,
41	    getChildrenOf: (ref: InternalVertexRef<T>) =>
42	      visible(ref) ? graph.getChildrenOf(ref) : null,
43	    requirePathsTo: (
44	      ref: InternalVertexRef<T>,
45	      options?: import('@core/ResolvedTree').GetPathToOptions,
46	    ) => {
47	      if (!visible(ref)) throw new Error('Unknown vertex reference');
48	      return graph
49	        .requirePathsTo(ref)
50	        .map((path) => path.filter(visible))
51	        .filter((path) =>
52	          graph.getParentsOf(path[0]!)!.every((parent) => !visible(parent)),
53	        )
54	        .map((path) => (options?.noSelf === true ? path.slice(0, -1) : path));
55	    },
56	  });
57	}
